#include "RegisterSourceScenarios.h"
#include <iostream>
#include <stdexcept>
#include <stop_token>
#include <type_traits>
using namespace dft::sequential;
static unsigned n=0;static void need(bool v,const char* m){++n;if(!v)throw std::runtime_error(m);}
static void bad(const auto& r,const char* m){need(!r&&r.error().code==hier::ErrorCode::BadRequest,m);}
static auto open(const char* f,const char* top){hier::model::OpenOptions o;o.files={f};o.tops={top};auto r=hier::Design::open(o);need(r.ok(),"open own RTL");return std::move(r.value());}
static auto request(const char* top){RegisterScenarioRequest r;r.common.resolveLogic=true;std::string p=std::string(top)+".mode";r.scenarios={{"ZERO",{{{p,0},false}}},{"ONE",{{{p,0},true}}},{"BACK",{{{p,0},false}}}};return r;}
int main(int argc,char** argv){try{
 need(argc==2,"fixture");static_assert(std::is_same_v<RegisterFactCoverage,struct RegisterChangedSignal>);std::stop_source stop;stop.request_stop();auto d=open(argv[1],"U_shared");StatisticsRequest rq;rq.scope="U_shared.u";auto st=registerStatistics(*d,rq);need(st.ok()&&st->complete,"statistics");RegisterControlOptions opt;opt.resolveLogic=true;auto p=profileRegisterControls(*d,*st,opt);need(p.ok()&&p->complete,"profile");auto g=registerControlGeneration(*d,*st,*p);need(g.ok()&&g->complete,"generation");
 auto fc=registerGenerationFanout(*st,*p,*g,{},stop.get_token());need(!fc&&fc.error().code==hier::ErrorCode::Cancelled,"fanout pre-cancel");RegisterFanoutLimits fl;fl.maxLinks=0;bad(registerGenerationFanout(*st,*p,*g,fl),"fanout bad budget");auto wrong=*g;wrong.graph.seeds[0].node=999999;bad(registerGenerationFanout(*st,*p,wrong),"fanout invalid seed");auto ps=*p;ps.snapshotId+="wrong";bad(registerGenerationFanout(*st,ps,*g),"fanout snapshot mismatch");
 auto sc=summarizeRegisterControlSources(*st,*p,*g,{},stop.get_token());need(!sc&&sc.error().code==hier::ErrorCode::Cancelled,"sources pre-cancel");RegisterSourceLimits sl;sl.maxSources=0;bad(summarizeRegisterControlSources(*st,*p,*g,sl),"source bad budget");bad(summarizeRegisterControlSources(*st,*p,wrong),"source invalid graph");
 d.reset();auto f=registerGenerationFanout(*st,*p,*g);need(f.ok()&&f->complete&&f->seeds.size()==2,"fanout pure after Design release/error reuse");size_t root=0;for(const auto& node:f->nodes)if(node.reaches.size()==2){++root;need(node.totals.factBits==13&&node.totals.coveredBits==9&&node.totals.overlapBits==4,"shared root union, not physical count");}need(root==1,"shared root one discovered graph node");auto src=summarizeRegisterControlSources(*st,*p,*g);need(src.ok()&&src->complete&&src->groups.size()==1&&src->groups[0].totals.coveredBits==9,"same terminal source union");
 fl={};fl.maxOrigins=1;auto pf=registerGenerationFanout(*st,*p,*g,fl);need(pf.ok()&&!pf->complete&&pf->origins.size()==1,"origin prefix retains global partial");sl={};sl.fanout.maxMembers=1;auto ss=summarizeRegisterControlSources(*st,*p,*g,sl);need(ss.ok()&&!ss->complete,"recomputed source does not upgrade fanout partial");
 st=hier::Error{hier::ErrorCode::BadRequest,"released"};p=hier::Error{hier::ErrorCode::BadRequest,"released"};g=hier::Error{hier::ErrorCode::BadRequest,"released"};need(!src->groups[0].source.kind.empty()&&!src->groups[0].signals[0].facts.empty()&&f->nodes.size()>=3,"pure outputs own values/containers after all inputs released");
 auto md=open(argv[1],"U_rewire");rq.scope="U_rewire.u";auto ms=registerStatistics(*md,rq);need(ms.ok(),"matrix statistics");auto mr=request("U_rewire");auto mc=compareRegisterSourceScenarios(*md,*ms,mr,{},stop.get_token());need(!mc&&mc.error().code==hier::ErrorCode::Cancelled,"matrix pre-cancel");RegisterSourceScenarioLimits ml;ml.maxCells=0;bad(compareRegisterSourceScenarios(*md,*ms,mr,ml),"matrix bad budget");auto br=mr;br.scenarios[1].name=std::string("bad")+static_cast<char>(0xff);bad(compareRegisterSourceScenarios(*md,*ms,br),"matrix strict UTF8");br=mr;br.scenarios[1].inputValues[0].input.path="absent";need(!compareRegisterSourceScenarios(*md,*ms,br),"second context error no partial success");auto stale=*ms;stale.snapshot.snapshotId+="wrong";bad(compareRegisterSourceScenarios(*md,stale,mr),"matrix snapshot mismatch");
 auto matrix=compareRegisterSourceScenarios(*md,*ms,mr);need(matrix.ok()&&matrix->complete&&matrix->rows.size()==1&&matrix->rows[0].status.size()==2,"matrix reusable after errors");need(matrix->rows[0].status[0]=="unchanged"&&matrix->rows[0].status[1]=="unchanged","same terminal bit union under 0/1/0");need(matrix->analysis.impacts[0].rows.size()==2&&matrix->analysis.impacts[0].rows[0].status=="changed"&&matrix->analysis.impacts[0].rows[1].status=="changed","deep structural change separately preserved");
 ml={};ml.generation.comparison.maxCones=1;auto independent=compareRegisterSourceScenarios(*md,*ms,mr,ml);need(independent.ok()&&!independent->complete&&independent->rows.size()==1&&independent->rows[0].status[0]=="unchanged","independent source proof under structure-only partial");ml={};ml.maxCells=1;auto atomic=compareRegisterSourceScenarios(*md,*ms,mr,ml);need(atomic.ok()&&!atomic->complete&&atomic->rows.empty()&&atomic->cells==0,"no half source row");
 md.reset();ms=hier::Error{hier::ErrorCode::BadRequest,"released"};need(matrix->scenarios[0].sources->groups[0].totals.coveredBits==9&&matrix->rows[0].source.kind=="primary_input","matrix owns source/path values after inputs release");
 auto mult=open(argv[1],"U_multiplicity");rq.scope="U_multiplicity";auto mts=registerStatistics(*mult,rq);need(mts.ok(),"multiplicity statistics");auto mm=compareRegisterSourceScenarios(*mult,*mts,request("U_multiplicity"));need(mm.ok()&&mm->complete&&mm->rows.size()==2,"multiplicity matrix");size_t changed=0,same=0;for(const auto& row:mm->rows){if(row.status[0]=="changed")++changed;else if(row.status[0]=="unchanged")++same;}need(changed==1&&same==1,"ignore factCount when original signal bit union unchanged");
 std::cout<<"{\"passed\":true,\"assertions\":"<<n<<"}\n";return 0;
 }catch(const std::exception& e){std::cerr<<"after "<<n<<" assertions: "<<e.what()<<'\n';return 1;}}
